-- Pantry entries, the append-only item event log and the expiry notification
-- log. See docs/data-model.md (pantry_entries, item_events,
-- expiry_notifications).
--
-- pantry_entries.id and item_events.id are generated by the client, so they
-- have no default. item_events.entry_id and catalog_item_id, and
-- expiry_notifications.entry_id, deliberately have no foreign keys: history
-- survives when an entry (or its catalog item) is deleted.
--
-- pantry_entries.catalog_item_id has no ON DELETE action (NO ACTION, not
-- RESTRICT), so deleting a household removes its custom catalog items and the
-- entries that point at them in one statement; the check runs at the end of
-- the statement, after both cascades. Deleting a catalog item that still has
-- entries fails.
--
-- Keeping updated_at current, checking that an entry's catalog item belongs to
-- its household, and writing events are the API's job (#19); there are no
-- triggers. Grants and row-level security come in #10.

-- +goose Up
CREATE TYPE stock_level AS ENUM ('full', 'half', 'low', 'out');

CREATE TYPE event_type AS ENUM (
    'entry_created',
    'level_changed',
    'expiry_changed',
    'location_changed',
    'purchase_date_changed',
    'entry_deleted'
);

CREATE TABLE pantry_entries (
    -- Client-generated UUIDv7; no default.
    id              uuid        PRIMARY KEY,
    household_id    uuid        NOT NULL REFERENCES households (id) ON DELETE CASCADE,
    catalog_item_id uuid        NOT NULL REFERENCES catalog_items (id),
    location_id     smallint    NOT NULL REFERENCES locations (id),
    -- No default: the API always sets it.
    level           stock_level NOT NULL,
    purchased_on    date        NOT NULL DEFAULT CURRENT_DATE,
    expires_on      date,
    created_by      uuid        REFERENCES users (id) ON DELETE SET NULL,
    updated_by      uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);

-- Grouped pantry view ("Milk x2").
CREATE INDEX pantry_entries_household_id_catalog_item_id_idx
    ON pantry_entries (household_id, catalog_item_id);

-- Expiry highlighting and the nightly push job.
CREATE INDEX pantry_entries_household_id_expires_on_idx
    ON pantry_entries (household_id, expires_on)
    WHERE expires_on IS NOT NULL;

CREATE TABLE item_events (
    -- Client-generated UUIDv7; no default. Retries insert with
    -- ON CONFLICT (id) DO NOTHING.
    id              uuid        PRIMARY KEY,
    household_id    uuid        NOT NULL REFERENCES households (id) ON DELETE CASCADE,
    -- No foreign keys: events outlive their entry and catalog item.
    entry_id        uuid        NOT NULL,
    catalog_item_id uuid        NOT NULL,
    actor_id        uuid        REFERENCES users (id) ON DELETE SET NULL,
    type            event_type  NOT NULL,
    changes         jsonb       NOT NULL DEFAULT '{}',
    -- Entry state after the event, so the feed works for deleted entries.
    snapshot        jsonb       NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now()
);

-- Latest change per entry ("Set to Low by Sam, 2h ago").
CREATE INDEX item_events_entry_id_occurred_at_idx
    ON item_events (entry_id, occurred_at DESC);

-- Household activity feed.
CREATE INDEX item_events_household_id_occurred_at_idx
    ON item_events (household_id, occurred_at DESC);

CREATE TABLE expiry_notifications (
    -- No foreign key: rows are deleted with the entry or age out (#22).
    entry_id   uuid        NOT NULL,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- Part of the key, so an edited expiry date can trigger a new alert.
    expires_on date        NOT NULL,
    sent_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (entry_id, user_id, expires_on)
);

-- +goose Down
DROP TABLE expiry_notifications;
DROP TABLE item_events;
DROP TABLE pantry_entries;
DROP TYPE event_type;
DROP TYPE stock_level;
